<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $ctrl = app(App\Http\Controllers\Admin\AdminEducationController::class); $r = new ReflectionMethod($ctrl, "syncTranslations"); $r->setAccessible(true); $pages = App\Models\Catalog\EducationPage::where("locale", "en")->orWhereNull("locale")->get(); foreach($pages as $p) { echo "Syncing {$p->slug}\n"; $p->locale = "en"; $p->save(); $r->invoke($ctrl, $p); } echo "Done!";
